    if(byteLength < 0){
        throw new IndexOutOfBoundsException("byteLength must be non-negative");
    }
    if(byteOffset < 0){
        throw new IndexOutOfBoundsException("byteOffset must be non-negative");
    }
    if(byteArrayValue != null){
        if(byteOffset + byteLength > byteArrayValue.length){
            throw new IndexOutOfBoundsException("byteOffset + byteLength exceeds source array length");
        }
    }
    int newLength = this.length + byteLength;
    if(newLength > data.length){
        enlarge(byteLength);
    }
    if(byteArrayValue != null){
        System.arraycopy(byteArrayValue, byteOffset, data, this.length, byteLength);
    } else {
        java.util.Arrays.fill(data, this.length, newLength, (byte)0);
    }
    this.length = newLength;
    return this;
}

