private int parseEndOfLine(String headerPart, int end) {
    try {
        if (headerPart == null || headerPart.isEmpty()) {
            return -1;
        }
        int length = headerPart.length();
        if (end < 0 || end >= length) {
            return -1;
        }
        // If the current position is already at a CR, check for the following LF
        if (headerPart.charAt(end) == '\r' && end + 1 < length && headerPart.charAt(end + 1) == '\n') {
            return end;
        }
        // Search for the next CRLF sequence starting from the current index
        int idx = headerPart.indexOf("\r\n", end);
        return idx;
    } catch (Exception e) {
        // In case of any unexpected error, return -1 to indicate failure
        return -1;
    }
}

