private Set<V> intersection(Set<V> set1, Set<V> set2) {
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }
    // Choose the smaller set to iterate for efficiency
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger  = set1.size() >  set2.size() ? set1 : set2;
    Set<V> result  = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

