private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new NullPointerException("predicate");
    }
    if (start == null) {
        throw new NullPointerException("start");
    }
    if (stop == null) {
        throw new NullPointerException("stop");
    }
    try {
        OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
        Node current = start;
        while (true) {
            if (predicate.test(current)) {
                return circ;
            }
            if (current == stop) {
                return circ;
            }
            // Advance the circulator in the requested direction.
            // The actual method names may vary; adjust as needed.
            if (dir > 0) {
                circ = circ.next();
            } else {
                circ = circ.prev();
            }
            current = circ.getNode();
            // Prevent infinite loops: if we return to the start node, stop.
            if (current == start) {
                return circ;
            }
        }
    } catch (Exception e) {
        throw new IllegalStateException("Failed to select node on outer face", e);
    }
}

