protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return null;
    }
    List<E> orderedEdges = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    Iterator<E> it = remaining.iterator();
    E first = it.next();
    orderedEdges.add(first);
    remaining.remove(first);
    V current = graph.getEdgeTarget(first);
    while (!remaining.isEmpty()) {
        boolean found = false;
        Iterator<E> iter = remaining.iterator();
        while (iter.hasNext()) {
            E e = iter.next();
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(current)) {
                orderedEdges.add(e);
                current = tgt;
                iter.remove();
                found = true;
                break;
            } else if (tgt.equals(current)) { // handle undirected case
                orderedEdges.add(e);
                current = src;
                iter.remove();
                found = true;
                break;
            }
        }
        if (!found) {
            return null; // cannot form a continuous tour
        }
    }
    double weight = 0.0;
    for (E e : orderedEdges) {
        weight += graph.getEdgeWeight(e);
    }
    V start = graph.getEdgeSource(orderedEdges.get(0));
    V end = graph.getEdgeTarget(orderedEdges.get(orderedEdges.size() - 1));
    return new GraphPathImpl<>(graph, start, end, orderedEdges, weight);
}

