private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    List<Integer> suffix = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        suffix.add(0);
    }
    long running = 0L;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null at index " + i);
        }
        running += val;
        suffix.set(i, (int) running);
    }
    return new Pair<>(suffix, running);
}

