private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) return result;
    for (K key : keys) {
        if (key == null) {
            result.add(null);
            continue;
        }
        Integer maxLower = null;
        for (K other : keys) {
            if (other == null || other == key) continue;
            try {
                int cmp = ((Comparable) key).compareTo(other);
                if (cmp > 0) {
                    int val = ((Number) other).intValue();
                    if (maxLower == null || val > maxLower) {
                        maxLower = val;
                    }
                }
            } catch (ClassCastException e) {
                // skip if not comparable or not a number
            }
        }
        result.add(maxLower);
    }
    return result;
}

