private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    java.util.List<Integer> bounds = new java.util.ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            bounds.add(0);
        } else {
            try {
                if (key instanceof Number) {
                    bounds.add(((Number) key).intValue());
                } else {
                    bounds.add(key.hashCode());
                }
            } catch (Exception e) {
                bounds.add(0);
            }
        }
    }
    return bounds;
}

