public Logger exists(String name) {
    if (name == null) {
        return null;
    }
    try {
        Logger logger = Logger.getLogger(name);
        // If the logger was just created, it typically has no level set and no handlers.
        // We consider it non‑existent if it has no level and no handlers and its parent is the root logger.
        if (logger.getLevel() == null && logger.getHandlers().length == 0) {
            Logger root = Logger.getLogger("");
            if (logger.getParent() == root) {
                return null;
            }
        }
        return logger;
    } catch (Exception e) {
        // In case of any unexpected error, treat as non‑existent.
        return null;
    }
}

