public Mappings diffStructure(String tableName, Mappings mappings) {
    try {
        if (tableName == null || mappings == null) {
            return null;
        }
        // Retrieve the current mapping for the given table name.
        Mappings current = getMapping(tableName);
        if (current == null) {
            return null;
        }
        Map<String, Object> currentSource = current.getSource();
        Map<String, Object> inputSource = mappings.getSource();
        if (currentSource == null) {
            return null;
        }
        // Exclude the _source configuration to avoid update conflicts.
        currentSource = new java.util.HashMap<>(currentSource);
        currentSource.remove("_source");
        // Build a map of fields that exist in the current mapping but not in the input mapping.
        Map<String, Object> diff = new java.util.LinkedHashMap<>();
        for (Map.Entry<String, Object> entry : currentSource.entrySet()) {
            if (inputSource == null || !inputSource.containsKey(entry.getKey())) {
                diff.put(entry.getKey(), entry.getValue());
            }
        }
        if (diff.isEmpty()) {
            return null;
        }
        // Create a new Mappings instance containing only the differing fields.
        Mappings result = new Mappings();
        result.setSource(diff);
        return result;
    } catch (Exception e) {
        // In case of any unexpected error, return null to indicate failure.
        return null;
    }
}

