    if (channels == null) {
        throw new IllegalArgumentException("channels cannot be null");
    }
    if (consumer == null) {
        throw new IllegalArgumentException("consumer cannot be null");
    }
    try {
        // Try to invoke a method named addTarget that accepts an IConsumer
        java.lang.reflect.Method addTarget = channels.getClass().getMethod("addTarget", IConsumer.class);
        addTarget.invoke(channels, consumer);
    } catch (NoSuchMethodException e) {
        // Fallback: try to get a list of targets and add the consumer
        try {
            java.lang.reflect.Method getTargets = channels.getClass().getMethod("getTargets");
            Object listObj = getTargets.invoke(channels);
            if (listObj instanceof java.util.List) {
                @SuppressWarnings("unchecked")
                java.util.List<IConsumer> list = (java.util.List<IConsumer>) listObj;
                list.add(consumer);
                return;
            }
        } catch (Exception ex) {
            // ignore
        }
        throw new RuntimeException("Unable to add consumer to channels");
    } catch (Exception e) {
        throw new RuntimeException("Failed to add new target", e);
    }
}

