public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("Provided file is null or does not exist");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return java.util.Collections.emptyList();
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    try (java.io.BufferedReader br = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            // Expected format: <timestamp>|<snapshotData>
            String[] parts = line.split("\\|", 2);
            if (parts.length < 2) {
                continue;
            }
            long ts;
            try {
                ts = Long.parseLong(parts[0]);
            } catch (NumberFormatException e) {
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                try {
                    java.lang.reflect.Method containsMethod = range.getClass().getMethod("contains", long.class);
                    if ((boolean) containsMethod.invoke(range, ts)) {
                        inRange = true;
                        break;
                    }
                } catch (Exception e) {
                    // If the method is not present, skip this range
                }
            }
            if (!inRange) {
                continue;
            }
            try {
                java.lang.reflect.Constructor<?> ctor = ThreadSnapshot.class.getConstructor(String.class);
                ThreadSnapshot snapshot = (ThreadSnapshot) ctor.newInstance(parts[1]);
                result.add(snapshot);
            } catch (Exception e) {
                // If snapshot cannot be constructed, skip this line
            }
        }
    }
    return result;
}

