private void pop(final String descriptor) {
    int index = 0;
    final int len = descriptor.length();
    // Helper to pop one slot from the stack
    java.util.function.IntConsumer popSlot = (ignored) -> {
        if (pos > 0) {
            stack[--pos] = null;
        } else {
            throw new IllegalStateException("Stack underflow while popping descriptor: " + descriptor);
        }
    };
    // Helper to pop a type (handles array, object, primitive)
    java.util.function.IntConsumer popType = (ignored) -> {
        char c = descriptor.charAt(index);
        if (c == '[') {
            // Skip all '[' characters
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            // Now at component type
            c = descriptor.charAt(index);
            if (c == 'L') {
                // Object type: skip until ';'
                index++; // skip 'L'
                while (descriptor.charAt(index) != ';') {
                    index++;
                }
                index++; // skip ';'
            } else {
                // Primitive type: just consume one char
                index++;
            }
            // Array occupies one slot
            popSlot.accept(0);
        } else if (c == 'L') {
            // Object type
            index++; // skip 'L'
            while (descriptor.charAt(index) != ';') {
                index++;
            }
            index++; // skip ';'
            popSlot.accept(0);
        } else {
            // Primitive type
            index++;
            if (c == 'J' || c == 'D') {
                // long or double occupy two slots
                popSlot.accept(0);
                popSlot.accept(0);
            } else {
                popSlot.accept(0);
            }
        }
    };

    if (len == 0) {
        return;
    }

    if (descriptor.charAt(0) == '(') {
        // Method descriptor: pop argument types
        index++; // skip '('
        while (index < len && descriptor.charAt(index) != ')') {
            popType.accept(0);
        }
    } else {
        // Type descriptor: pop the single type
        popType.accept(0);
    }
}

