public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure desiredCapacity is at least 3
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }
    // Compute maximum allowed capacity if desiredCapacity >= 1000
    long maxCap = candidate;
    if (desiredCapacity >= 1000) {
        maxCap = Math.min((long)desiredCapacity + (long)(desiredCapacity * 0.11) + 1, Integer.MAX_VALUE);
    }
    while (candidate <= maxCap) {
        if (isPrime(candidate)) {
            return candidate;
        }
