public static int computeUTF8Size(final CharSequence str,final int index,final int len){
    if (str == null) {
        throw new IllegalArgumentException("str must not be null");
    }
    if (index < 0 || len < 0 || index + len > str.length()) {
        throw new IllegalArgumentException("index and len out of bounds");
    }
    int size = 0;
    int end = index + len;
    for (int i = index; i < end; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // high surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    // valid surrogate pair
                    size += 4;
                    i++; // skip low surrogate
                } else {
                    // invalid surrogate pair
                    size += 3; // replacement char
                }
            } else {
                // high surrogate at end
                size += 3;
            }
        } else if (ch >= 0xDC00 && ch <= 0xDFFF) { // low surrogate alone
            size += 3;
        } else {
            size += 3;
        }
    }
    return size;
}

